input.command:
python3 - <<'EOF'
p='src/adapters/paddock.rs'
s=open(p).read()
old='''        Ok(Some(Self::renewed(gateway, id, ending, timing)))
    }
'''
new='''        // The id goes in a header and a path, so it is held to what paddock writes.
        if id.is_empty() || !id.bytes().all(|b| b.is_ascii_alphanumeric()) {
            return Err(format!(
                "`POST /paddock/leases` granted an id that cannot go in a header, \\
                 so kelpie refused the take: {id:?}"
            ));
        }
        Ok(Some(Self::renewed(gateway, id, ending, timing)))
    }

    /// The id paddock granted, exactly as it wrote it
    pub(crate) fn id(&self) -> &str {
        &self.id
    }
'''
assert old in s
s=s.replace(old,new,1)
open(p,'w').write(s)
EOF
cargo test --lib adapters::paddock --no-run 2>&1 | tail -5

